CREATE TABLE IF NOT EXISTS drawing_structure_versions (id TEXT PRIMARY KEY,project_id TEXT NOT NULL,document_id TEXT NOT NULL,document_version_id TEXT NOT NULL,drawing_intake_version_id TEXT NOT NULL,version_number INTEGER NOT NULL,input_fingerprint TEXT NOT NULL,output_fingerprint TEXT NOT NULL,parser_version TEXT NOT NULL,status TEXT NOT NULL,summary TEXT NOT NULL,review_status TEXT NOT NULL DEFAULT 'Needs Review',superseded_at TEXT,created_by TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(project_id) REFERENCES projects(id),FOREIGN KEY(document_id) REFERENCES documents(id),FOREIGN KEY(document_version_id) REFERENCES document_versions(id),FOREIGN KEY(drawing_intake_version_id) REFERENCES drawing_intake_versions(id));
CREATE UNIQUE INDEX IF NOT EXISTS drawing_structure_document_version_idx ON drawing_structure_versions(document_id,version_number);
CREATE INDEX IF NOT EXISTS drawing_structure_current_idx ON drawing_structure_versions(document_id,superseded_at);
CREATE TABLE IF NOT EXISTS drawing_structure_tables (id TEXT PRIMARY KEY,structure_version_id TEXT NOT NULL,table_key TEXT NOT NULL,page_number INTEGER NOT NULL,table_type TEXT NOT NULL,bounding_box TEXT NOT NULL,row_count INTEGER NOT NULL,column_count INTEGER NOT NULL,detection_confidence INTEGER NOT NULL,detection_method TEXT NOT NULL,review_status TEXT NOT NULL DEFAULT 'Needs Review',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(structure_version_id) REFERENCES drawing_structure_versions(id));
CREATE UNIQUE INDEX IF NOT EXISTS drawing_structure_table_key_idx ON drawing_structure_tables(structure_version_id,table_key);
CREATE TABLE IF NOT EXISTS drawing_structure_rows (id TEXT PRIMARY KEY,table_id TEXT NOT NULL,row_number INTEGER NOT NULL,bounding_box TEXT,structural_confidence INTEGER NOT NULL,structural_status TEXT NOT NULL,physical_row_count INTEGER NOT NULL,review_status TEXT NOT NULL DEFAULT 'Needs Review',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(table_id) REFERENCES drawing_structure_tables(id));
CREATE UNIQUE INDEX IF NOT EXISTS drawing_structure_row_idx ON drawing_structure_rows(table_id,row_number);
CREATE TABLE IF NOT EXISTS drawing_structure_columns (id TEXT PRIMARY KEY,table_id TEXT NOT NULL,column_number INTEGER NOT NULL,bounding_box TEXT NOT NULL,width REAL NOT NULL,header_candidate TEXT,confidence INTEGER NOT NULL,review_status TEXT NOT NULL DEFAULT 'Needs Review',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(table_id) REFERENCES drawing_structure_tables(id));
CREATE UNIQUE INDEX IF NOT EXISTS drawing_structure_column_idx ON drawing_structure_columns(table_id,column_number);
CREATE TABLE IF NOT EXISTS drawing_structure_cells (id TEXT PRIMARY KEY,table_id TEXT NOT NULL,row_id TEXT NOT NULL,column_id TEXT NOT NULL,row_number INTEGER NOT NULL,column_number INTEGER NOT NULL,bounding_box TEXT NOT NULL,raw_content TEXT NOT NULL,reconstructed_content TEXT NOT NULL,original_fragments TEXT NOT NULL,confidence INTEGER NOT NULL,review_status TEXT NOT NULL DEFAULT 'Needs Review',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(table_id) REFERENCES drawing_structure_tables(id),FOREIGN KEY(row_id) REFERENCES drawing_structure_rows(id),FOREIGN KEY(column_id) REFERENCES drawing_structure_columns(id));
CREATE UNIQUE INDEX IF NOT EXISTS drawing_structure_cell_idx ON drawing_structure_cells(table_id,row_number,column_number);
CREATE TABLE IF NOT EXISTS drawing_structure_headers (id TEXT PRIMARY KEY,table_id TEXT NOT NULL,column_id TEXT NOT NULL,header_type TEXT NOT NULL,raw_content TEXT NOT NULL,bounding_box TEXT NOT NULL,source_fragment_ids TEXT NOT NULL,confidence INTEGER NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(table_id) REFERENCES drawing_structure_tables(id),FOREIGN KEY(column_id) REFERENCES drawing_structure_columns(id));
CREATE INDEX IF NOT EXISTS drawing_structure_header_idx ON drawing_structure_headers(table_id,header_type);
CREATE TABLE IF NOT EXISTS drawing_structure_regions (id TEXT PRIMARY KEY,structure_version_id TEXT NOT NULL,region_key TEXT NOT NULL,page_number INTEGER NOT NULL,region_type TEXT NOT NULL,bounding_box TEXT NOT NULL,raw_content TEXT NOT NULL,source_fragments TEXT NOT NULL,confidence INTEGER NOT NULL,detection_method TEXT NOT NULL,review_status TEXT NOT NULL DEFAULT 'Needs Review',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(structure_version_id) REFERENCES drawing_structure_versions(id));
CREATE UNIQUE INDEX IF NOT EXISTS drawing_structure_region_key_idx ON drawing_structure_regions(structure_version_id,region_key);
CREATE TABLE IF NOT EXISTS drawing_structure_legend_rows (id TEXT PRIMARY KEY,table_id TEXT NOT NULL,row_id TEXT NOT NULL,source_page INTEGER NOT NULL,source_row INTEGER NOT NULL,symbol_geometry TEXT NOT NULL,abbreviation TEXT,description TEXT,notes TEXT,bounding_box TEXT,structural_confidence INTEGER NOT NULL,review_status TEXT NOT NULL DEFAULT 'Needs Review',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(table_id) REFERENCES drawing_structure_tables(id),FOREIGN KEY(row_id) REFERENCES drawing_structure_rows(id));
CREATE UNIQUE INDEX IF NOT EXISTS drawing_structure_legend_row_idx ON drawing_structure_legend_rows(table_id,source_row);
CREATE TABLE IF NOT EXISTS drawing_structure_validation_issues (id TEXT PRIMARY KEY,structure_version_id TEXT NOT NULL,table_id TEXT NOT NULL,row_id TEXT,column_id TEXT,page_number INTEGER NOT NULL,issue_type TEXT NOT NULL,severity TEXT NOT NULL,bounding_box TEXT,detail TEXT NOT NULL,confidence INTEGER NOT NULL,status TEXT NOT NULL DEFAULT 'Open',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(structure_version_id) REFERENCES drawing_structure_versions(id),FOREIGN KEY(table_id) REFERENCES drawing_structure_tables(id));
CREATE INDEX IF NOT EXISTS drawing_structure_issue_idx ON drawing_structure_validation_issues(structure_version_id,status,severity);
CREATE TABLE IF NOT EXISTS drawing_structure_audit_events (id TEXT PRIMARY KEY,project_id TEXT NOT NULL,document_id TEXT NOT NULL,structure_version_id TEXT NOT NULL,action TEXT NOT NULL,previous_value TEXT,new_value TEXT NOT NULL,reason TEXT NOT NULL,actor_user_id TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(structure_version_id) REFERENCES drawing_structure_versions(id));
CREATE INDEX IF NOT EXISTS drawing_structure_audit_idx ON drawing_structure_audit_events(document_id,created_at);
